const { IPC } = require(ROOT + '/dist/electron/shared/ipc.js');
const { registerIpcHandlers } = require(ROOT + '/dist/electron/main/ipc.js');
const { createOverlayWindow } = require(ROOT + '/dist/electron/main/window.js');
const { showMenuWindow } = require(ROOT + '/dist/electron/main/menuWindow.js');
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
app.setAppPath(ROOT);
