    console.log('battle button:', btn);
    await sleep(8000);
    await shot(menu, '/tmp/desmon-menu-battle-result.png');
    await shot(win, '/tmp/desmon-overlay-after-pvp.png');
    console.log('SHOT_OK'); app.exit(0);
  }
});
