    11	const DDL = `
    12	CREATE TABLE IF NOT EXISTS players (
    13	  id uuid PRIMARY KEY,
    14	  token_hash text NOT NULL UNIQUE,
    15	  nickname text NOT NULL,
    16	  snapshot jsonb,
    17	  best_index integer NOT NULL DEFAULT 0,
    18	  rebirths integer NOT NULL DEFAULT 0,
    19	  stolen_ids jsonb NOT NULL DEFAULT '[]',
    20	  last_pvp_at double precision,
    21	  updated_at timestamptz NOT NULL DEFAULT now()
    22	);
    23	CREATE INDEX IF NOT EXISTS players_score_idx ON players (best_index DESC, rebirths DESC);
    24	`;
    25	
    26	/** jsonb columns arrive parsed and `double precision` arrives as a number. */
    27	const toRow = (r: Record<string, unknown>): PlayerRow => ({
    28	  id: r['id'] as string,
    29	  name: r['nickname'] as string,
    30	  snapshot: r['snapshot'] as Snapshot | null,
    31	  stolenIds: r['stolen_ids'] as string[],
    32	  lastPvpAt: r['last_pvp_at'] as number | null,
    33	});
