    35	export class PgStore implements Store {
    36	  private constructor(private readonly pool: Pool) {}
    37	
    38	  /** Builds the pool, runs the idempotent DDL, and returns the store. */
    39	  static async connect(connectionString: string): Promise<PgStore> {
    40	    // Render's internal URL has a bare host and no TLS; the external one needs
    41	    // TLS but presents a certificate we cannot chain to a public root.
    42	    const ssl = /\.render\.com$/.test(new URL(connectionString).hostname)
    43	      ? { rejectUnauthorized: false }
    44	      : undefined;
    45	    const pool = new Pool({ connectionString, ssl });
    46	    await pool.query(DDL);
    47	    return new PgStore(pool);
    48	  }
    49	
    50	  async createPlayer(p: { id: string; tokenHash: string; name: string }): Promise<void> {
    51	    await this.pool.query('INSERT INTO players (id, token_hash, nickname) VALUES ($1, $2, $3)', [
    52	      p.id,
    53	      p.tokenHash,
    54	      p.name,
    55	    ]);
    56	  }
    57	
    58	  async getByToken(tokenHash: string): Promise<PlayerRow | null> {
    59	    return this.one('SELECT * FROM players WHERE token_hash = $1', [tokenHash]);
    60	  }
    61	
    62	  async getById(id: string): Promise<PlayerRow | null> {
    63	    return this.one('SELECT * FROM players WHERE id = $1', [id]);
    64	  }
    65	
    66	  async putSnapshot(id: string, snapshot: Snapshot): Promise<void> {
    67	    await this.pool.query(
    68	      'UPDATE players SET snapshot = $2::jsonb, best_index = $3, rebirths = $4, nickname = $5, updated_at = now() WHERE id = $1',
    69	      [id, JSON.stringify(snapshot), snapshot.bestIndex, snapshot.rebirths, snapshot.name],
    70	    );
    71	  }
    72	
    73	  async setStolenIds(id: string, ids: string[]): Promise<void> {
    74	    await this.pool.query('UPDATE players SET stolen_ids = $2::jsonb WHERE id = $1', [
    75	      id,
    76	      JSON.stringify(ids),
    77	    ]);
    78	  }
    79	
    80	  async setLastPvpAt(id: string, at: number): Promise<void> {
    81	    await this.pool.query('UPDATE players SET last_pvp_at = $2 WHERE id = $1', [id, at]);
    82	  }
