    84	  async rank(key: ScoreKey): Promise<number> {
    85	    const { rows } = await this.pool.query(
    86	      'SELECT count(*)::int AS n FROM players WHERE snapshot IS NOT NULL AND (best_index, rebirths) > ($1, $2)',
    87	      [key.bestIndex, key.rebirths],
    88	    );
