    90	  }
    91	
    92	  async top(n: number): Promise<PlayerRow[]> {
    93	    const { rows } = await this.pool.query(
    94	      'SELECT * FROM players WHERE snapshot IS NOT NULL ORDER BY best_index DESC, rebirths DESC, updated_at ASC LIMIT $1',
    95	      [n],
    96	    );
    97	    return rows.map(toRow);
    98	  }
    99	
   100	  async neighbor(excludeId: string, key: ScoreKey, dir: 'up' | 'down'): Promise<PlayerRow | null> {
   101	    const sql =
   102	      dir === 'up'
   103	        ? 'SELECT * FROM players WHERE id <> $1 AND snapshot IS NOT NULL AND (best_index, rebirths) > ($2, $3) ORDER BY best_index ASC, rebirths ASC, updated_at DESC LIMIT 1'
   104	        : 'SELECT * FROM players WHERE id <> $1 AND snapshot IS NOT NULL AND (best_index, rebirths) <= ($2, $3) ORDER BY best_index DESC, rebirths DESC, updated_at ASC LIMIT 1';
