     9	
    10	import { randomBytes } from 'node:crypto';
    11	import { LEADERBOARD_DEFAULT } from '../shared/api.js';
    12	import { createNetClient, toSnapshot, type NetClient } from '../main/net.js';
    13	
    14	/** Generous: Render's free dyno cold-starts in ~60 s, far past NET_TIMEOUT_MS. */
    15	export const PROBE_TIMEOUT_MS = 90_000;
    16	
    17	export interface ProbeResult {
    18	  playerId: string;
    19	  rank: number;
    20	}
    21	
    22	/** A throwaway nickname `probe-<4hex>` (matches NICK_RE). */
    23	export function probeName(randomHex: (bytes: number) => string): string {
    24	  return `probe-${randomHex(2)}`;
    25	}
    26	
    27	/**
    28	 * register → upload `{ bestIndex: 0, rebirths: 0, companions: [] }` (ranks
    29	 * last, disturbs nobody) → leaderboard, asserting the probe got a rank.
    30	 * Rejects with the first failing step; never plays a battle.
    31	 */
    32	export async function runProbe(client: NetClient, name: string): Promise<ProbeResult> {
    33	  const registered = await client.register(name);
    34	  if (!registered.ok) throw new Error(`register failed: ${registered.error}`);
    35	  const { playerId, token } = registered.value;
    36	
    37	  const snapshot = toSnapshot(name, { bestIndex: 0, rebirths: 0, companions: [] });
    38	  const uploaded = await client.upload(token, snapshot);
    39	  if (!uploaded.ok) throw new Error(`upload failed: ${uploaded.error}`);
    40	
    41	  const board = await client.leaderboard(token, LEADERBOARD_DEFAULT);
    42	  if (!board.ok) throw new Error(`leaderboard failed: ${board.error}`);
    43	  const me = board.value.me;
    44	  if (me === null) throw new Error(`leaderboard returned no row for ${name}`);
    45	  if (me.rank < 1) throw new Error(`leaderboard rank ${me.rank} < 1 for ${name}`);
    46	
    47	  return { playerId, rank: me.rank };
    48	}
    49	
    50	async function main(baseUrl: string): Promise<void> {
    51	  if (baseUrl === '') {
    52	    console.error('usage: node dist/electron/server/probe.js <url>');
    53	    process.exitCode = 1;
    54	    return;
    55	  }
    56	  const client = createNetClient({ baseUrl, timeoutMs: PROBE_TIMEOUT_MS });
    57	  try {
    58	    console.log(JSON.stringify(await runProbe(client, probeName((n) => randomBytes(n).toString('hex')))));
    59	  } catch (err) {
    60	    console.error(`[probe] ${String(err)}`);
    61	    process.exitCode = 1;
    62	  }
    63	}
