     1	// Big-number presentation — SPEC F28 (Assumption 20, GAME_DESIGN_V2 §1).
     2	// Pure: no electron/DOM/node imports. Truncates, never rounds.
     3	
     4	/** Bijective base-26 group suffix: 1→A, 26→Z, 27→AA, 702→ZZ, 703→AAA; g ≤ 0 → ''. */
     5	export function suffix(g: number): string {
     6	  let out = '';
     7	  for (let k = Math.floor(g); k > 0; k = Math.floor((k - 1) / 26)) {
     8	    out = String.fromCharCode(65 + ((k - 1) % 26)) + out;
     9	  }
    10	  return out;
    11	}
    12	
    13	/** 3 significant digits + A–Z suffix: 999 → '999', 1000 → '1.00A', 1e6 → '1.00B'. */
    14	export function format(n: bigint | number): string {
    15	  if (typeof n === 'number' && !Number.isFinite(n)) return '0';
    16	  const v = typeof n === 'number' ? BigInt(Math.floor(n)) : n;
    17	  if (v < 0n) return '0';
    18	  const s = v.toString();
    19	  const d = s.length;
    20	  if (d <= 3) return s;
    21	  const g = Math.floor((d - 1) / 3);
    22	  const lead = d - 3 * g;
    23	  const m = s.slice(0, 3);
    24	  return (lead === 3 ? m : `${m.slice(0, lead)}.${m.slice(lead)}`) + suffix(g);
    25	}
    26	
    27	/** num/den as a number clamped to [0, 1], 4 decimal places; den ≤ 0n → 0. */
    28	export function ratio(num: bigint, den: bigint): number {
    29	  if (den <= 0n) return 0;
    30	  return Math.min(1, Math.max(0, Number((num * 10000n) / den) / 10000));
    31	}
    32	
    33	/** Save-file big-number field: finite number → floored digits, digit string → itself, else null. */
    34	export function bigField(raw: unknown): string | null {
    35	  if (typeof raw === 'number') {
    36	    return Number.isFinite(raw) ? String(Math.max(0, Math.floor(raw))) : null;
    37	  }
    38	  return typeof raw === 'string' && /^\d+$/.test(raw) ? raw : null;
    39	}
