    20	export interface Fever {
    21	  /** The last FEVER_INPUTS input timestamps, oldest first. */
    22	  readonly stamps: readonly number[];
    23	  /** Clock value at which the current fever stops (0 = not burning). */
    24	  readonly activeUntil: number;
    25	  /** Clock value before which no new fever can be lit. */
    26	  readonly cooldownUntil: number;
