    37	 * window, when nothing is burning and the cooldown has passed; the stamps are
    38	 * cleared on start so the burst is spent.
    39	 */
    40	export function feverInput(f: Fever, nowMs: number): { fever: Fever; started: boolean } {
    41	  const stamps = [...f.stamps, nowMs].slice(-FEVER_INPUTS);
    42	  const started =
    43	    stamps.length === FEVER_INPUTS &&
    44	    nowMs - (stamps[0] ?? nowMs) <= FEVER_WINDOW_MS &&
    45	    !feverActive(f, nowMs) &&
    46	    nowMs >= f.cooldownUntil;
    47	  return started
    48	    ? { fever: { stamps: [], activeUntil: nowMs + FEVER_MS, cooldownUntil: 0 }, started }
