   226	 * call and the victim draw is consumed even when nobody can be stolen.
   227	 * ponytail: no bot or cooldown rules here, those are the server's.
   228	 */
   229	export function resolvePvp(
   230	  attacker: readonly Companion[],
   231	  defender: readonly Companion[],
   232	  rng: Rng,
   233	): { attackerWon: boolean; moved: Companion | null; attackerPower: bigint; defenderPower: bigint } {
   234	  const sum = (cs: readonly Companion[]): bigint =>
   235	    cs.reduce((total, c) => total + companionPower(c), 0n);
   236	  const attackerPower = sum(attacker);
   237	  const defenderPower = sum(defender);
   238	  const total = attackerPower + defenderPower;
   239	  const attackerWon = rng.next() < (total === 0n ? 0.5 : ratio(attackerPower, total));
   240	  const loser = attackerWon ? defender : attacker;
   241	  const victim = loser[Math.floor(rng.next() * loser.length)] ?? null;
   242	  const winner = attackerWon ? attacker : defender;
   243	  return {
   244	    attackerWon,
   245	    moved: winner.length >= ROSTER_CAP ? null : victim,
   246	    attackerPower,
   247	    defenderPower,
   248	  };
   249	}
