    52	/** JSON body of `res`, or undefined when it is missing/unparsable (never throws). */
    53	async function readJson(res: Response): Promise<unknown> {
    54	  try {
    55	    return (await res.json()) as unknown;
    56	  } catch {
    57	    return undefined;
    58	  }
