    61	/**
    62	 * HTTP client for `/v1` (SERVER_ARCHITECTURE §3). `baseUrl === ''` means
    63	 * offline: every method resolves `{ ok: false, error: 'offline' }` and fetch is
    64	 * never called.
    65	 */
    66	export function createNetClient(o: {
    67	  baseUrl: string;
    68	  fetchFn?: typeof fetch;
    69	  timeoutMs?: number;
    70	}): NetClient {
    71	  const { baseUrl, fetchFn = fetch, timeoutMs = NET_TIMEOUT_MS } = o;
    72	
    73	  async function call<T>(
    74	    method: string,
    75	    path: string,
    76	    token: string | null,
    77	    body?: unknown,
    78	  ): Promise<NetResult<T>> {
    79	    if (baseUrl === '') return { ok: false, error: 'offline' };
    80	    let res: Response;
    81	    try {
    82	      res = await fetchFn(`${baseUrl}${path}`, {
    83	        method,
    84	        headers: token === null
    85	          ? { 'content-type': 'application/json' }
    86	          : { 'content-type': 'application/json', authorization: `Bearer ${token}` },
    87	        body: body === undefined ? undefined : JSON.stringify(body),
    88	        signal: AbortSignal.timeout(timeoutMs),
    89	      });
    90	    } catch {
    91	      return { ok: false, error: 'network' };
    92	    }
    93	    if (res.status === 401) return { ok: false, error: 'unauthorized' };
    94	    const parsed = await readJson(res);
    95	    if (res.ok && parsed !== undefined) return { ok: true, value: parsed as T };
    96	    const error = (typeof parsed === 'object' && parsed !== null ? parsed : {}) as ApiError;
    97	    if (res.status === 429 && error.error === 'cooldown') {
    98	      return { ok: false, error: 'cooldown', retryAfterSec: error.retryAfterSec };
    99	    }
   100	    return { ok: false, error: 'server', status: res.status };
   101	  }
   102	
   103	  return {
   104	    register: (name) => call<RegisterResponse>('POST', '/v1/players', null, { nickname: name }),
   105	    upload: (token, snapshot) => call<SnapshotResponse>('PUT', '/v1/snapshot', token, snapshot),
   106	    leaderboard: (token, n) => call<LeaderboardResponse>('GET', `/v1/leaderboard?n=${n}`, token),
   107	    pvp: (token) => call<PvpResponse>('POST', '/v1/pvp', token, {}),
   108	  };
   109	}
   110	
   111	/**
   112	 * Owns identity.json, lazy registration, the dirty roster key, the sync moments
   113	 * and the once-per-session re-register after a 401 (SERVER_ARCHITECTURE §6).
   114	 */
   115	export function createNetSession(deps: {
   116	  client: NetClient;
   117	  userDataDir: string;
   118	  online: boolean;
   119	  randomUUID: () => string;
   120	}): NetSession {
   121	  const { client, userDataDir, online, randomUUID } = deps;
   122	  let identity: Identity = readIdentity(userDataDir, randomUUID);
   123	  /** Last save handed to the session; the source of every upload. */
   124	  let lastSave: SnapshotSource | null = null;
   125	  /** Roster key the server already has; null = nothing uploaded yet. */
   126	  let syncedKey: string | null = null;
   127	  let reRegistered = false;
   128	
   129	  /** bestIndex is deliberately absent: kills at the frontier must not spam PUTs. */
   130	  const rosterKey = (save: SnapshotSource): string =>
   131	    JSON.stringify([identity.name, save.rebirths, save.companions]);
   132	
   133	  const payload = (): IdentityPayload => ({ name: identity.name, playerId: identity.playerId, online });
   134	
   135	  const store = (next: Identity): void => {
   136	    identity = next;
   137	    writeIdentity(userDataDir, next);
   138	  };
   139	
   140	  async function ensureRegistered(): Promise<NetResult<string>> {
   141	    if (identity.token !== null) return { ok: true, value: identity.token };
   142	    const res = await client.register(identity.name);
   143	    if (!res.ok) return res;
   144	    store({ name: identity.name, playerId: res.value.playerId, token: res.value.token });
   145	    return { ok: true, value: res.value.token };
   146	  }
   147	
   148	  /** Registers if needed, then runs `send`; a 401 re-registers and retries ONCE per session. */
   149	  async function withToken<T>(send: (token: string) => Promise<NetResult<T>>): Promise<NetResult<T>> {
   150	    const first = await ensureRegistered();
   151	    if (!first.ok) return first;
   152	    const res = await send(first.value);
   153	    if (res.ok || res.error !== 'unauthorized' || reRegistered) return res;
   154	    reRegistered = true;
   155	    store({ name: identity.name, playerId: null, token: null });
   156	    const second = await ensureRegistered();
   157	    if (!second.ok) return second;
   158	    return send(second.value);
   159	  }
   160	
   161	  async function upload(): Promise<NetResult<SnapshotResponse> | null> {
   162	    if (lastSave === null) return null;
   163	    const key = rosterKey(lastSave);
   164	    const snapshot = toSnapshot(identity.name, lastSave);
   165	    const res = await withToken((token) => client.upload(token, snapshot));
   166	    if (res.ok) syncedKey = key;
   167	    return res;
   168	  }
   169	
   170	  const uploadIfDirty = async (): Promise<NetResult<SnapshotResponse> | null> =>
   171	    lastSave !== null && rosterKey(lastSave) !== syncedKey ? upload() : null;
   172	
   173	  /** Companion ids the server stripped on the pre-flight upload, for the menu to drop. */
   174	  const removedOf = (res: NetResult<SnapshotResponse> | null): string[] =>
   175	    res !== null && res.ok ? res.value.removed : [];
   176	
   177	  return {
   178	    identity() {
   179	      void uploadIfDirty();
   180	      return payload();
   181	    },
   182	    setName(name) {
   183	      if (isValidName(name)) store({ ...identity, name });
   184	      return payload();
   185	    },
   186	    onSave(save) {
   187	      lastSave = save;
   188	      void uploadIfDirty();
   189	    },
   190	    async leaderboard(n) {
   191	      const removed = removedOf(await uploadIfDirty());
   192	      const res = await withToken((token) => client.leaderboard(token, n));
   193	      return res.ok ? { ok: true, value: { ...res.value, removed } } : res;
   194	    },
   195	    async pvp() {
   196	      const removed = removedOf(await upload());
   197	      const res = await withToken((token) => client.pvp(token));
   198	      return res.ok ? { ok: true, value: { ...res.value, removed } } : res;
   199	    },
   200	  };
   201	}
