     7	import { mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
     8	import { join } from 'node:path';
     9	import { NICK_RE } from '../shared/api.js';
    10	
    11	export const IDENTITY_FILE_NAME = 'identity.json';
    12	
    13	export interface Identity {
    14	  name: string;
    15	  playerId: string | null;
    16	  token: string | null;
    17	}
    18	
    19	/** Absolute path of identity.json inside the given userData directory. */
    20	export function identityFilePath(userDataDir: string): string {
    21	  return join(userDataDir, IDENTITY_FILE_NAME);
    22	}
    23	
    24	/** A fresh unregistered nickname: 'Knight-' + the first 4 chars of a uuid. */
    25	export function defaultName(randomUUID: () => string): string {
    26	  return `Knight-${randomUUID().slice(0, 4)}`;
    27	}
    28	
    29	/** True when `name` satisfies the nickname rule (1–16 of A–Z a–z 0–9 _ -). */
    30	export function isValidName(name: unknown): name is string {
    31	  return typeof name === 'string' && NICK_RE.test(name);
    32	}
    33	
    34	/**
    35	 * Read identity.json. Missing, unreadable, corrupt or wrongly shaped content
    36	 * yields a fresh `{ name: 'Knight-xxxx', playerId: null, token: null }`.
    37	 * Never throws.
    38	 */
    39	export function readIdentity(dir: string, randomUUID: () => string): Identity {
    40	  let raw: unknown = null;
    41	  try {
    42	    raw = JSON.parse(readFileSync(identityFilePath(dir), 'utf8')) as unknown;
    43	  } catch {
    44	    raw = null;
    45	  }
    46	  const o = (typeof raw === 'object' && raw !== null ? raw : {}) as Record<string, unknown>;
    47	  return {
    48	    name: isValidName(o.name) ? o.name : defaultName(randomUUID),
    49	    playerId: typeof o.playerId === 'string' ? o.playerId : null,
    50	    token: typeof o.token === 'string' ? o.token : null,
    51	  };
    52	}
    53	
    54	/** Atomically persist `identity` (tmp + rename). Returns false, never throws. */
    55	export function writeIdentity(dir: string, identity: Identity): boolean {
    56	  const target = identityFilePath(dir);
    57	  const tmp = `${target}.tmp`;
    58	  try {
    59	    mkdirSync(dir, { recursive: true });
    60	    writeFileSync(tmp, JSON.stringify(identity), 'utf8');
    61	    renameSync(tmp, target);
    62	    return true;
    63	  } catch {
    64	    try {
    65	      unlinkSync(tmp);
    66	    } catch {
    67	      // best effort: the tmp file may never have been created
    68	    }
    69	    return false;
    70	  }
    71	}
