    53	function narrowAction(payload: unknown): CollectionAction | null {
    54	  const a = (payload ?? {}) as Record<string, unknown>;
    55	  const str = (k: string): boolean => typeof a[k] === 'string';
    56	  const obj = (k: string): boolean => typeof a[k] === 'object' && a[k] !== null;
