    89	export interface IpcOptions {
    90	  /** Fired when the renderer reports its first painted frame (smoke, T13). */
    91	  onFirstFrame?: () => void;
    92	}
    93	
    94	/** Register all renderer→main handlers. Call once, before the window loads. */
    95	export function registerIpcHandlers(options: IpcOptions = {}): void {
    96	  // SPEC F49: smoke runs offline BY CODE — an empty baseUrl makes the net
    97	  // client resolve `{ ok: false, error: 'offline' }` without ever calling
    98	  // fetch, so `npm run smoke` needs no network and no server.
    99	  const baseUrl = process.env.SMOKE ? '' : (process.env.DESMON_SERVER_URL ?? SERVER_URL);
   100	  const session = createNetSession({
   101	    client: createNetClient({ baseUrl }),
   102	    userDataDir: app.getPath('userData'),
   103	    online: baseUrl !== '',
   104	    randomUUID,
   105	  });
   106	
   107	  // Live state from the T04 global-input state machine; before/without
   108	  // startGlobalInput (e.g. SMOKE=1) it reports the fallback default.
   109	  ipcMain.handle(IPC.GET_INPUT_MODE, (): InputModePayload => getCurrentInputMode());
   110	
   111	  // Raw parsed JSON or null — validation is core's job (T08).
   112	  ipcMain.handle(IPC.LOAD_STATE, (): unknown => readSaveFile(app.getPath('userData')));
   113	
   114	  ipcMain.handle(IPC.SAVE_STATE, (event, data: unknown): void => {
   115	    writeSaveFile(app.getPath('userData'), data);
   116	    // The renderer's save is untrusted input: parse it, never cast it. The
   117	    // session uploads in the background and its result is deliberately
   118	    // dropped — main never pushes roster changes at the game window.
   119	    const parsed = parseSave(data);
   120	    session.onSave(parsed);
   121	    // …but the OTHER window (the menu) is showing a save it did not write.
   122	    sendToOthers(event.sender, IPC.STATE_CHANGED, parsed);
   123	  });
   124	
   125	  // Menu → game relay (SPEC F51). Unknown/malformed actions are ignored.
   126	  ipcMain.handle(IPC.MENU_ACTION, (event, payload: unknown): void => {
   127	    const action = narrowAction(payload);
   128	    if (action !== null) {
   129	      sendToOthers(event.sender, IPC.ACTION, action);
   130	    }
   131	  });
   132	
   133	  ipcMain.handle(IPC.GET_IDENTITY, (): IdentityPayload => session.identity());
   134	
   135	  ipcMain.handle(IPC.SET_NAME, (_event, payload: unknown): IdentityPayload => {
   136	    const { name } = (payload as Partial<SetNamePayload> | null | undefined) ?? {};
   137	    return session.setName(name);
   138	  });
   139	
   140	  ipcMain.handle(IPC.LEADERBOARD, (_event, p: unknown): Promise<NetResult<LeaderboardResult>> => {
   141	    const { n } = (p as Partial<LeaderboardQueryPayload> | null | undefined) ?? {};
   142	    const count =
   143	      typeof n === 'number' && Number.isFinite(n)
   144	        ? Math.min(Math.max(Math.trunc(n), 1), LEADERBOARD_MAX)
   145	        : LEADERBOARD_DEFAULT;
   146	    return session.leaderboard(count);
   147	  });
   148	
   149	  ipcMain.handle(IPC.PVP, (): Promise<NetResult<PvpResult>> => session.pvp());
   150	
   151	  ipcMain.handle(IPC.OPEN_ACCESSIBILITY_SETTINGS, async (): Promise<void> => {
   152	    await shell.openExternal(ACCESSIBILITY_SETTINGS_URL);
   153	  });
   154	
   155	  // The menu's single boot path: answer the SENDER with the save on disk.
   156	  ipcMain.on(IPC.MENU_READY, (event) => {
   157	    event.sender.send(IPC.STATE_CHANGED, parseSave(readSaveFile(app.getPath('userData'))));
   158	  });
   159	
   160	  ipcMain.on(IPC.FIRST_FRAME, () => {
   161	    options.onFirstFrame?.();
   162	  });
   163	
   164	  // Whole-window drag (SPEC Assumption 10): the renderer streams cursor
   165	  // deltas while a drag is in flight; moving the window that SENT the event
   166	  // keeps this handler stateless. Deltas are validated — a compromised
   167	  // renderer must not be able to throw the window to NaN-land.
   168	  ipcMain.on(IPC.MOVE_WINDOW, (event, payload: unknown) => {
   169	    const win = BrowserWindow.fromWebContents(event.sender);
   170	    if (win === null) {
   171	      return;
   172	    }
   173	    const delta = payload as Partial<MoveWindowPayload> | null | undefined;
   174	    const dx = typeof delta?.dx === 'number' && Number.isFinite(delta.dx) ? Math.round(delta.dx) : 0;
   175	    const dy = typeof delta?.dy === 'number' && Number.isFinite(delta.dy) ? Math.round(delta.dy) : 0;
   176	    if (dx === 0 && dy === 0) {
   177	      return;
   178	    }
   179	    const [x = 0, y = 0] = win.getPosition();
   180	    win.setPosition(x + dx, y + dy);
   181	  });
   182	}

