    39	/** Every companion as a card, strongest first, ties → lower id. */
    40	export function rosterRows(save: SaveFile): RosterRow[] {
    41	  return [...save.companions]
    42	    .sort((a, b) => {
    43	      const pa = companionPower(a);
    44	      const pb = companionPower(b);
    45	      if (pa === pb) return idNum(a.id) - idNum(b.id);
    46	      return pb > pa ? 1 : -1;
    47	    })
    48	    .map((c) => ({
    49	      id: c.id,
    50	      speciesId: c.speciesId,
    51	      stars: c.stars,
    52	      name: companionName(c),
    53	      starText: `★×${String(c.stars)}`,
    54	      power: format(companionPower(c)),
