    59	/** Every unordered pair that may fuse: same species AND same stars. */
    60	export function fuseCandidates(save: SaveFile): [string, string][] {
    61	  const cs = save.companions;
    62	  const pairs: [string, string][] = [];
    63	  for (let i = 0; i < cs.length; i++) {
    64	    for (let j = i + 1; j < cs.length; j++) {
    65	      const a = cs[i];
    66	      const b = cs[j];
    67	      if (a && b && a.speciesId === b.speciesId && a.stars === b.stars) {
    68	        pairs.push([a.id, b.id]);
    69	      }
    70	    }
    71	  }
    72	  return pairs;
    73	}
