   102	/** The server's top, plus my own line when the top does not already hold it. */
   103	export function leaderboardRows(result: NetResult<LeaderboardResult>): RankRow[] {
   104	  if (!result.ok) {
   105	    const name = result.error === 'cooldown' ? 'Cooldown' : 'Offline';
   106	    return [{ rank: '', name, deepest: '', rebirths: '' }];
   107	  }
   108	  const { top, me } = result.value;
